      ok(imp.left >= box.right && imp.top < box.bottom && imp.bottom > box.top, "it sits beside the date box, where the calendar cannot cover it");
      const top = document.elementFromPoint(imp.left + imp.width / 2, imp.top + imp.height / 2);
