    eq(slideLayout(lines("Results (2025 / 2026)", "Up", "Down")).title, "Results (2025 / 2026)", "an ordinary title keeps its brackets");
    const curve = slideLayout(lines("Quality rises (Quality / Time)", "~ Learn", "~ Reminder", "~ Stuck"));
