    eq(pick("(o) A", "(o) B").layout, "list", "a cycle needs three");
    eq(pick("| Build", "| Buy").layout, "split");
    eq(pick("| A", "| B", "| C", "| D").layout, "quadrant");
    eq(pick("| A", "| B", "| C").layout, "list", "| on three lines");
