    eq(T("", "One, two, three\nfour"), "null", "uneven separators are not a table");
    eq(T("", "| a | b |\n| --- | --- |\n| 1 | 2 |"), "null", "a Markdown table already is one");
    eq(T("", "City\tQ1"), "null", "one line is not a table");
